"""Build the bilingual portfolio from curated content and shared assets."""
from pathlib import Path
from html import escape
from urllib.parse import quote
import json
import shutil

BASE = Path(__file__).resolve().parent
OUT = BASE / 'dist'
CONTENT = json.loads((BASE / 'content.json').read_text())
PROJECTS = CONTENT['PROJECTS']
INSIGHTS = CONTENT['INSIGHTS']
EMAIL = 'emmanuelakounna@gmail.com'
LINKEDIN = 'https://www.linkedin.com/in/akounna'
ORIGIN = 'https://hugues-emmanuel-akounna.emmanuelakounna.chatgpt.site'
NAV = [('', 'Accueil', 'Home'), ('apropos', 'Parcours', 'About'), ('expertises', 'Compétences', 'Expertise'), ('projets', 'Projets', 'Projects'), ('publications', 'Publications', 'Writing'), ('ressources', 'Ressources', 'Resources'), ('services', 'Services', 'Services')]
TAGS = {'Tous':'All', 'Économie':'Economics', 'Données':'Data', 'Développement':'Development', 'Finance':'Finance', 'Agriculture':'Agriculture', 'Numérique':'Digital', 'IA':'AI'}


def tr(lang, fr, en):
    return en if lang == 'en' else fr


def path(lang, route=''):
    return '/' + ('en/' if lang == 'en' else '') + (route.strip('/') + '/' if route else '')


def txt(lang, item, key):
    return item[key + '_en'] if lang == 'en' else item[key]


def tag(lang, value):
    return TAGS.get(value, value) if lang == 'en' else value


def esc(value):
    return escape(str(value), quote=True)


def link(href, label, cls='text-link'):
    return f'<a class="{cls}" href="{esc(href)}">{escape(label)} <span aria-hidden="true">↗</span></a>'


def eyebrow(label):
    return f'<p class="eyebrow"><span aria-hidden="true"></span>{escape(label)}</p>'


def tags(lang, values):
    return '<div class="tags">' + ''.join(f'<span>{escape(tag(lang,t))}</span>' for t in values) + '</div>'


def image_asset(name, eager=False, cls=''):
    """Images are decorative illustrations, not documentation of the projects."""
    media = {
        'trade': ('trade-illustration.webp', 2056, 765),
        'desk': ('research-desk.webp', 1122, 1402),
        'agriculture': ('agriculture-editorial.webp', 1536, 1024),
    }
    filename, width, height = media[name]
    priority = 'fetchpriority="high"' if eager else 'loading="lazy"'
    return f'<img class="{cls}" src="/assets/images/{filename}" alt="" width="{width}" height="{height}" decoding="async" {priority}>'


def editorial_image(kind, index=0, eager=False):
    names = ['trade', 'desk', 'agriculture', 'agriculture'] if kind == 'projects' else ['trade', 'desk', 'desk']
    return image_asset(names[index % len(names)], eager=eager)


def pagehead(lang, label, title, desc):
    return f'<section class="pagehead wrap">{eyebrow(label)}<h1>{title}</h1><p class="lead">{escape(desc)}</p></section>'


def cta(lang):
    return f'''<section class="cta"><div class="wrap cta-inner"><div>{eyebrow(tr(lang,'Travailler ensemble','Working together'))}<h2>{tr(lang,'Discutons de votre étude<br>ou de votre projet.','Let’s discuss your study<br>or your project.')}</h2><p>{tr(lang,'Vous préparez une étude économique, une analyse de données ou un projet de développement ? Écrivez-moi avec votre question et le contexte du travail.','Are you preparing an economic study, data analysis or development project? Write to me with your question and the context of the work.')}</p></div>{link(path(lang,'contact'),tr(lang,'Proposer une collaboration','Discuss a collaboration'),'btn btn-lime')}</div></section>'''


def layout(lang, route, title, description, body):
    active = route.split('/')[0]
    other = 'en' if lang == 'fr' else 'fr'
    nav = ''.join(f'<a class="nav-link {"active" if s == active else ""}" href="{path(lang,s)}" {"aria-current=page" if s == active else ""}>{en if lang == "en" else fr}</a>' for s,fr,en in NAV)
    switch = f'<a class="lang-switch" href="{path(other,route)}" lang="{other}" aria-label="{tr(lang,"Read this page in English","Lire cette page en français")}"><span {"class=selected" if lang=="fr" else ""}>FR</span><span aria-hidden="true">/</span><span {"class=selected" if lang=="en" else ""}>EN</span></a>'
    return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#172d43"><meta name="robots" content="noindex,nofollow"><title>{escape(title)} — Hugues Emmanuel Akounna</title><meta name="description" content="{esc(description)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="alternate" hreflang="fr" href="{ORIGIN}{path('fr',route)}"><link rel="alternate" hreflang="en" href="{ORIGIN}{path('en',route)}"><link rel="stylesheet" href="/assets/style.css"><link rel="stylesheet" href="/assets/premium.css"><script defer src="/assets/site.js"></script></head>
<body class="page-{active or 'home'}"><a class="skip" href="#main">{tr(lang,'Aller au contenu','Skip to content')}</a>
<header class="site-header"><div class="header-inner"><a class="brand" href="{path(lang)}" aria-label="Hugues Emmanuel Akounna — {tr(lang,'accueil','home')}"><span class="brand-monogram" aria-hidden="true">h<span>.</span>a</span><span class="brand-name">Hugues Emmanuel<br><strong>Akounna</strong></span></a><nav class="nav" id="site-nav" aria-label="{tr(lang,'Navigation principale','Main navigation')}">{nav}<a class="nav-mobile-contact" href="{path(lang,'contact')}">{tr(lang,'Collaborer','Collaborate')} ↗</a></nav><div class="header-tools">{switch}{link(path(lang,'contact'),tr(lang,'Collaborer','Collaborate'),'header-contact')}<button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav"><span>Menu</span><span class="menu-icon" aria-hidden="true"><i></i><i></i></span></button></div></div></header>
<main id="main">{body}</main>
<footer class="footer"><div class="wrap footer-grid"><div class="footer-intro"><a class="footer-brand" href="{path(lang)}">Hugues Emmanuel<br>Akounna<span>.</span></a><p>{tr(lang,'Recherche en économie appliquée et analyse de données.<br>Basé en Afrique de l’Ouest, ouvert aux projets internationaux.','Applied economics research and data analysis.<br>Based in West Africa, open to international projects.')}</p><span class="location"><span aria-hidden="true">◎</span> Cotonou, {tr(lang,'Bénin','Benin')}</span></div><div><span class="footer-label">{tr(lang,'Explorer','Explore')}</span><a href="{path(lang,'projets')}">{tr(lang,'Projets','Projects')}</a><a href="{path(lang,'publications')}">{tr(lang,'Publications & notes','Writing & notes')}</a><a href="{path(lang,'ressources')}">{tr(lang,'Ressources','Resources')}</a></div><div><span class="footer-label">{tr(lang,'Faire connaissance','Get to know me')}</span><a href="{path(lang,'apropos')}">{tr(lang,'Mon parcours','My background')}</a><a href="{path(lang,'expertises')}">{tr(lang,'Compétences','Expertise')}</a><a href="{path(lang,'services')}">{tr(lang,'Services','Services')}</a></div><div><span class="footer-label">{tr(lang,'Échanger','Connect')}</span><a href="mailto:{EMAIL}">Email ↗</a><a href="{LINKEDIN}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="{path(lang,'contact')}">{tr(lang,'Contact & collaboration','Contact & collaboration')}</a></div></div><div class="wrap foot-bottom"><span>© 2026 Hugues Emmanuel Akounna</span><span>{tr(lang,'Économie appliquée et politiques de développement','Applied economics and development policy')}</span><a href="#main">{tr(lang,'Retour en haut','Back to top')} ↑</a></div></footer></body></html>'''


def visual(lang):
    labels = tr(lang,['Économie','Données','Développement','Finance','IA & numérique'],['Economics','Data','Development','Finance','AI & digital'])
    return f'''<aside class="research-visual"><div class="visual-top"><span>{tr(lang,'Mes sujets de travail','My areas of work')}</span></div><div class="orbit">{''.join(f'<span class="orbit-label">{label}</span>' for label in labels)}</div><div class="visual-bottom"><span class="research-number">15</span><span>{tr(lang,'pays dans le panel de mon mémoire','countries in my thesis panel')}<small>CEDEAO / ECOWAS · 2000-2023</small></span></div></aside>'''


def card(lang, item, kind, index=0):
    route = 'projets' if kind=='projects' else 'publications'
    title = txt(lang,item,'title'); summary = txt(lang,item,'summary')
    searchable = ' '.join([title,summary,txt(lang,item,'kind'),item['year'],*(tag(lang,t) for t in item['tags'])])
    type_key = ('research' if index < 3 else 'field') if kind == 'projects' else ('research' if index == 0 else 'methods')
    reading = max(1,round(len(' '.join(txt(lang,item,'paragraphs')).split())/180)) if kind != 'projects' else None
    return f'''<article class="work-card filter-item" data-tags="{esc('|'.join(item['tags']))}" data-search="{esc(searchable)}" data-year="{item['year']}" data-type="{type_key}"><div class="card-meta"><span>{item['year']} / {index+1:02d}</span><span class="card-type">{escape(txt(lang,item,'kind'))}</span></div><div class="card-art art-{index%4}" aria-hidden="true">{editorial_image(kind,index)}<span>{tr(lang,['TRANSFORMATION','FINANCE','AGRICULTURE','TERRAIN'][index%4],['TRANSFORMATION','FINANCE','AGRICULTURE','FIELDWORK'][index%4]) if kind=='projects' else tr(lang,['RECHERCHE','MÉTHODE','INTELLIGENCE'][index%3],['RESEARCH','METHOD','INTELLIGENCE'][index%3])}</span><i></i><b>{'↗' if kind=='projects' else 'Aa'}</b></div><div class="card-body"><h3><a href="{path(lang,route+'/'+item['slug'])}">{escape(title)}</a></h3><p>{escape(summary)}</p><div class="card-foot">{tags(lang,item['tags'])}{link(path(lang,route+'/'+item['slug']),tr(lang,'Voir le projet','View project') if kind=='projects' else tr(lang,'Lire la note','Read note'))}</div></div>{f'<span class="reading-time">{reading} min {tr(lang,"de lecture","read")}</span>' if reading else ''}</article>'''


def filters(lang, items, kind):
    available = ['Tous'] + [t for t in TAGS if t != 'Tous' and any(t in p['tags'] for p in items)]
    buttons=''.join(f'<button type="button" class="filter-btn {"selected" if i==0 else ""}" data-filter="{esc(t)}" aria-pressed="{"true" if i==0 else "false"}">{escape(tag(lang,t))}</button>' for i,t in enumerate(available))
    options = [('all',tr(lang,'Tous les formats','All formats')),('research',tr(lang,'Recherche','Research')),('field',tr(lang,'Terrain','Fieldwork'))] if kind=='projects' else [('all',tr(lang,'Tous les formats','All formats')),('research',tr(lang,'Note de recherche','Research note')),('methods',tr(lang,'Méthode & pratique','Method & practice'))]
    opts=''.join(f'<option value="{v}">{label}</option>' for v,label in options)
    return f'''<section class="wrap collection" data-filter-root><div class="filter-heading"><h2>{tr(lang,'Explorer les travaux','Explore the work')}</h2><span class="filter-count" aria-live="polite">{len(items)} {tr(lang,'résultats','results')}</span></div><div class="filter-buttons" role="group" aria-label="{tr(lang,'Filtrer par thème','Filter by topic')}">{buttons}</div><div class="search-row"><label class="search-label"><span class="search-icon" aria-hidden="true">⌕</span><span class="sr-only">{tr(lang,'Rechercher un sujet, une méthode, un mot-clé','Search a topic, method or keyword')}</span><input type="search" class="filter-search" placeholder="{tr(lang,'Rechercher un sujet, une méthode…','Search a topic or method…')}"></label><label class="select-label"><span>{tr(lang,'Format','Format')}</span><select class="filter-type">{opts}</select></label><label class="select-label"><span>{tr(lang,'Trier','Sort')}</span><select class="filter-sort"><option value="newest">{tr(lang,'Plus récents','Newest first')}</option><option value="oldest">{tr(lang,'Plus anciens','Oldest first')}</option><option value="title">{tr(lang,'Titre A-Z','Title A-Z')}</option></select></label></div><noscript><p class="article-note">{tr(lang,'Tous les travaux sont accessibles ci-dessous. Activez JavaScript pour utiliser les filtres.','All work is available below. Enable JavaScript to use the filters.')}</p></noscript><div class="cards-grid">{''.join(card(lang,p,kind,i) for i,p in enumerate(items))}</div><div class="empty-state" hidden><span aria-hidden="true">⌕</span><h3>{tr(lang,'Aucun résultat pour ces critères.','No matches for these filters.')}</h3><p>{tr(lang,'Essayez un autre thème ou un mot-clé plus court.','Try another topic or a shorter keyword.')}</p><button type="button" class="reset-filters btn btn-dark">{tr(lang,'Réinitialiser les filtres','Reset filters')} ↗</button></div></section>'''


def home(lang):
    hero=f'''<section class="hero wrap">{image_asset("trade",eager=True,cls="hero-backdrop")}<div class="hero-grid"><div class="hero-copy">{eyebrow(tr(lang,'Économie appliquée · Afrique & international','Applied economics · Africa & beyond'))}<h1>{tr(lang,'Comprendre les économies<br><em>par les données<br>et le terrain.</em>','Understanding economies<br><em>through data<br>and fieldwork.</em>')}</h1><p class="hero-intro">{tr(lang,'Je suis Hugues Emmanuel Akounna. Je travaille sur des questions d’économie appliquée et de développement. J’utilise la recherche et les données pour comprendre les changements économiques et éclairer les décisions.','I am Hugues Emmanuel Akounna. I work on applied economics and development questions, using research and data to understand economic change and inform decisions.')}</p><div class="hero-actions">{link(path(lang,'projets'),tr(lang,'Explorer mes travaux','Explore my work'),'btn btn-dark')}{link(path(lang,'apropos'),tr(lang,'Faire connaissance','Get to know me'))}</div><p class="hero-location"><span class="status-dot" aria-hidden="true"></span>{tr(lang,'Basé au Bénin · ouvert aux collaborations internationales','Based in Benin · open to international collaboration')}</p></div>{visual(lang)}</div></section>'''
    strip=f'''<div class="scope-strip"><div class="wrap"><span>{tr(lang,'Mes domaines de travail','My areas of work')}</span><p>{tr(lang,'Économie','Economics')}<i>+</i>{tr(lang,'Données','Data')}<i>+</i>{tr(lang,'Développement','Development')}<i>+</i>{tr(lang,'IA','AI')}<i>+</i>Finance</p></div></div>'''
    featured=f'''<section class="section wrap"><div class="section-heading"><div>{eyebrow(tr(lang,'Mon mémoire de master','My master’s thesis'))}<h2>{tr(lang,'Le numérique et la production<br>dans les pays de la CEDEAO.','Digital adoption and production<br>in ECOWAS countries.')}</h2></div>{link(path(lang,'projets'),tr(lang,'Tous les projets','All projects'))}</div><a class="featured" href="{path(lang,'projets/digitalisation-cedeao')}"><div class="feature-atlas">{editorial_image("projects",0)}<div class="atlas-top"><span>{tr(lang,'Terrain d’étude','Research scope')}</span><span>CEDEAO / ECOWAS</span></div><div class="atlas-big">15<span>{tr(lang,'économies','economies')}</span></div><div class="country-grid">{''.join(f'<span>{x}</span>' for x in ['BEN','BFA','CPV','CIV','GMB','GHA','GIN','GNB','LBR','MLI','NER','NGA','SEN','SLE','TGO'])}</div><div class="atlas-bottom"><strong>2000-2023</strong><span>{tr(lang,'Panel de pays','Country panel')}</span></div></div><div class="feature-copy"><span class="status-badge">{tr(lang,'Mémoire de master · en révision','Master’s thesis · under review')}</span><h3>{escape(txt(lang,PROJECTS[0],'title'))}</h3><p>{escape(txt(lang,PROJECTS[0],'summary'))}</p><div class="feature-points"><span>01 · {tr(lang,'Valeur ajoutée industrielle','Industrial value added')}</span><span>02 · {tr(lang,'Diversification des exportations','Export diversification')}</span></div><span class="text-link">{tr(lang,'Découvrir la question et la démarche','Explore the question and approach')} <span aria-hidden="true">↗</span></span></div></a></section>'''
    domains=[('economie','01',tr(lang,'Économie & développement','Economics & development'),tr(lang,'Trajectoires productives, agriculture et politiques publiques.','Productive change, agriculture and public policy.')),('donnees','02',tr(lang,'Données & économétrie','Data & econometrics'),tr(lang,'Je documente les indicateurs et le code pour pouvoir vérifier les analyses.','I document indicators and code so the analysis can be checked.')),('frontieres','03',tr(lang,'Finance, IA & numérique','Finance, AI & digital'),tr(lang,'Je m’intéresse aux changements de la production et aux nouveaux usages numériques.','I study changes in production and new digital uses.'))]
    areas=f'''<section class="section band"><div class="wrap"><div class="section-heading"><div>{eyebrow(tr(lang,'Mes compétences','My expertise'))}<h2>{tr(lang,'Mes domaines de travail.','My areas of work.')}</h2></div>{link(path(lang,'expertises'),tr(lang,'Mes compétences','My expertise'))}</div><div class="topic-grid">{''.join(f'<a href="{path(lang,"expertises")}#{id}"><span class="topic-num">{n}</span><h3>{title}</h3><p>{desc}</p><span class="topic-image" aria-hidden="true">{image_asset({"economie":"agriculture","donnees":"desk","frontieres":"trade"}[id])}</span><span class="topic-arrow" aria-hidden="true">↗</span></a>' for id,n,title,desc in domains)}</div></div></section>'''
    selected=f'''<section class="section wrap"><div class="section-heading"><div>{eyebrow(tr(lang,'Recherche et terrain','Research and fieldwork'))}<h2>{tr(lang,'Quelques projets<br><em>sur lesquels je travaille.</em>','Some of the projects<br><em>I work on.</em>')}</h2></div>{link(path(lang,'projets'),tr(lang,'Explorer les projets','Explore projects'))}</div><div class="cards-grid">{card(lang,PROJECTS[2],'projects',2)}{card(lang,PROJECTS[1],'projects',1)}</div></section>'''
    notes=f'''<section class="section band"><div class="wrap"><div class="section-heading"><div>{eyebrow(tr(lang,'Publications et notes','Writing and notes'))}<h2>{tr(lang,'Des notes sur l’économie<br><em>et les méthodes de recherche.</em>','Notes on economics<br><em>and research methods.</em>')}</h2></div>{link(path(lang,'publications'),tr(lang,'Toutes les notes','All writing'))}</div><div class="notes-list">{''.join(f'<a href="{path(lang,"publications/"+p["slug"])}"><span class="note-thumb" aria-hidden="true">{editorial_image("insights",i)}</span><span class="note-num">{i+1:02d}</span><div><span class="card-meta">{escape(txt(lang,p,"kind"))}</span><h3>{escape(txt(lang,p,"title"))}</h3></div><span class="note-arrow" aria-hidden="true">↗</span></a>' for i,p in enumerate(INSIGHTS))}</div></div></section>'''
    return hero+strip+home_about(lang)+areas+featured+selected+notes+cta(lang)


def home_about(lang):
    return f'''<section class="section wrap home-about"><div class="about-collage" aria-hidden="true"><div class="collage-main">{image_asset('desk')}</div><div class="collage-small">{image_asset('agriculture')}</div><span class="collage-mark">h.a</span></div><div class="about-copy">{eyebrow(tr(lang,'Mon parcours','My background'))}<h2>{tr(lang,'Mon travail en<br><em>économie appliquée.</em>','My work in<br><em>applied economics.</em>')}</h2><p>{tr(lang,'Je me forme à l’économie appliquée et aux politiques de développement à l’Université d’Abomey-Calavi. Mes travaux portent sur les économies ouest-africaines, notamment l’agriculture, la transformation structurelle et les usages numériques.','I study applied economics and development policy at the Université d’Abomey-Calavi. My work focuses on West African economies, including agriculture, structural transformation and digital adoption.')}</p><div class="about-facts"><div><span>{tr(lang,'Recherche et données','Research and data')}</span><p>{tr(lang,'Diagnostics et estimations sous Stata.','Diagnostics and estimates in Stata.')}</p></div><div><span>{tr(lang,'Expérience de terrain','Field experience')}</span><p>{tr(lang,'Statistiques agricoles au SESSEC de la DDAEP Zou.','Agricultural statistics at SESSEC, DDAEP Zou.')}</p></div></div>{link(path(lang,'apropos'),tr(lang,'Découvrir mon parcours','Read about my background'),'btn btn-dark')}</div></section>'''


def about(lang):
    intro=pagehead(lang,tr(lang,'Mon parcours','My background'),tr(lang,'Mon parcours en<br><em>économie appliquée.</em>','My background in<br><em>applied economics.</em>'),tr(lang,'Je suis Hugues Emmanuel Akounna, économiste en formation à l’Université d’Abomey-Calavi. Je travaille sur les questions de développement à partir de la recherche appliquée et des méthodes quantitatives.','I am Hugues Emmanuel Akounna, an economist in training at the Université d’Abomey-Calavi. I study development questions through applied research and quantitative methods.'))
    timeline=[('2024-2026',tr(lang,'Master 2 · Économie appliquée et politiques de développement','Master’s · Applied economics and development policy'),tr(lang,'Université d’Abomey-Calavi. Mémoire en révision, soutenance à préparer.','Université d’Abomey-Calavi. Thesis under review, defence to prepare.')),('2023',tr(lang,'Licence · Économie et gestion des exploitations agricoles','Undergraduate degree · Agricultural economics and farm management'),tr(lang,'Université d’Abomey-Calavi. Mémoire sur l’irrigation et la sécurité alimentaire des maraîchers.','Université d’Abomey-Calavi. Dissertation on irrigation and food security among market gardeners.')),('2022-2023',tr(lang,'Stage · Statistiques agricoles & suivi','Internship · Agricultural statistics & monitoring'),tr(lang,'SESSEC, DDAEP Zou. Participation à la collecte, au traitement des données et au suivi des indicateurs agricoles.','SESSEC, DDAEP Zou. Contributed to data collection, processing and agricultural indicator monitoring.'))]
    body=f'''<section class="wrap split-content"><div class="prose"><h2>{tr(lang,'Les questions qui m’intéressent','The questions I study')}</h2><p>{tr(lang,'Les économies évoluent différemment selon les secteurs et les territoires. J’étudie ces écarts avec les données disponibles. Je cherche à comprendre ce qu’elles montrent, les questions qui restent ouvertes et ce que l’analyse peut apporter aux décisions.','Economic change differs between sectors and places. I study those differences using the available data. I want to understand what the data show, which questions remain open and how the analysis can inform decisions.')}</p><p>{tr(lang,'Vivre au Bénin nourrit mon intérêt pour les économies ouest-africaines. Mes travaux portent sur l’agriculture et la transformation structurelle, ainsi que sur le développement financier et les usages numériques. Je souhaite contribuer à des projets de recherche et de développement en Afrique et à l’international.','Living in Benin informs my interest in West African economies. My work covers agriculture and structural transformation, as well as financial development and digital adoption. I want to contribute to research and development projects in Africa and internationally.')}</p><h2>{tr(lang,'Formation & expérience','Education & experience')}</h2><div class="timeline">{''.join(f'<div><span>{year}</span><div><h3>{title}</h3><p>{desc}</p></div></div>' for year,title,desc in timeline)}</div></div><aside class="profile-card"><div class="profile-monogram" aria-hidden="true">{editorial_image("insights",2)}<span class="profile-initials">h<span>.</span>a</span></div><h2>Hugues Emmanuel<br>Akounna</h2><p>{tr(lang,'Économie · données · développement','Economics · data · development')}</p><dl><div><dt>{tr(lang,'Lieu de travail','Based in')}</dt><dd>Cotonou, {tr(lang,'Bénin','Benin')}</dd></div><div><dt>{tr(lang,'Outils de travail','Working tools')}</dt><dd>Stata · Excel · Office</dd></div><div><dt>{tr(lang,'Langues','Languages')}</dt><dd>{tr(lang,'Français courant<br>Anglais en progression (A2)','Fluent French<br>Developing English (A2)')}</dd></div><div><dt>{tr(lang,'Collaborations','Collaboration')}</dt><dd>{tr(lang,'Recherche, missions d’analyse & projets internationaux','Research, analytical assignments & international projects')}</dd></div></dl>{link(path(lang,'contact'),tr(lang,'Faisons connaissance','Let’s connect'),'btn btn-dark')}</aside></section>'''
    return intro+body+cta(lang)


def expertise(lang):
    blocks=[('economie','01',tr(lang,'Économie & développement','Economics & development'),tr(lang,'Je pars d’une question économique pour construire l’analyse. Je prends en compte le secteur étudié et les institutions qui influencent son évolution.','I start with an economic question and build the analysis around it, taking the sector and its institutional context into account.'),tr(lang,['Transformation structurelle & trajectoires sectorielles','Agriculture & sécurité alimentaire','Revue de littérature & synthèse de politiques'],['Structural transformation & sector pathways','Agriculture & food security','Literature reviews & policy synthesis'])),('donnees','02',tr(lang,'Données & économétrie','Data & econometrics'),tr(lang,'Je construis les indicateurs et vérifie les propriétés des données avant d’analyser les résultats. Je précise aussi les limites de l’interprétation.','I construct indicators and check the properties of the data before analysing the findings. I also explain the limits of the interpretation.'),tr(lang,['Nettoyage, structuration & contrôle qualité','Données de panel & diagnostics sous Stata','Tableaux, visualisations & reporting'],['Cleaning, structuring & quality checks','Panel data & diagnostics in Stata','Tables, visualisation & reporting'])),('frontieres','03',tr(lang,'Finance, IA & numérique','Finance, AI & digital'),tr(lang,'J’étudie les changements dans la production et j’apprends à utiliser les nouveaux outils d’analyse, notamment dans les domaines de la finance, du numérique et de l’IA.','I study changes in production and learn to use new analytical tools, particularly in finance, digital technologies and AI.'),tr(lang,['Développement financier & productivité sectorielle','Diffusion des TIC & transformation productive','IA comme appui à la recherche, avec vérification humaine'],['Financial development & sector productivity','ICT adoption & productive transformation','AI as research support, with human verification']))]
    rows=''.join(f'<article id="{id}" class="expertise-row"><span class="row-num">{n}</span><div><h2>{title}</h2><p>{desc}</p><ul class="skill-list">'+''.join(f'<li>{s}</li>' for s in skills)+'</ul></div></article>' for id,n,title,desc,skills in blocks)
    tools=f'''<section class="wrap tools-section"><div class="section-heading"><div>{eyebrow(tr(lang,'Mes outils de travail','My working tools'))}<h2>{tr(lang,'Les outils que j’utilise<br><em>dans mes travaux.</em>','The tools I use<br><em>in my work.</em>')}</h2></div></div><div class="tool-columns"><div><h3>{tr(lang,'Analyse & données','Analysis & data')}</h3><div class="tool-tags"><span>Stata</span><span>Excel</span></div><p>{tr(lang,'Préparation des données, indicateurs, diagnostics et estimations.','Data preparation, indicators, diagnostics and estimation.')}</p></div><div><h3>{tr(lang,'Restitution & communication','Reporting & communication')}</h3><div class="tool-tags"><span>Word</span><span>PowerPoint</span><span>Adobe</span><span>Figma</span></div><p>{tr(lang,'Rapports, notes, présentations et supports visuels lisibles.','Readable reports, briefs, presentations and visual materials.')}</p></div></div></section>'''
    return pagehead(lang,tr(lang,'Compétences & axes de recherche','Expertise & research interests'),tr(lang,'Analyse économique<br><em>et méthodes quantitatives.</em>','Economic analysis<br><em>and quantitative methods.</em>'),tr(lang,'J’utilise l’économie appliquée et l’analyse quantitative pour étudier les questions de développement. La présentation des résultats fait aussi partie de mon travail.','I use applied economics and quantitative analysis to study development questions. Communicating the findings is also part of my work.'))+f'<section class="wrap expertise-list">{rows}</section>'+tools+cta(lang)


def detail_project(lang,p):
    idx=PROJECTS.index(p)
    sections=[('question',tr(lang,'La question de départ','The starting question'),txt(lang,p,'context')),('methode',tr(lang,'La démarche','The approach'),txt(lang,p,'method')),('lecture',tr(lang,'Lecture & limites','Interpretation & limitations'),txt(lang,p,'finding'))]
    prose=''.join(f'<section id="{id}"><span class="section-num">{i+1:02d}</span><h2>{escape(h)}</h2><p>{escape(t)}</p></section>' for i,(id,h,t) in enumerate(sections))
    aside=f'''<aside class="detail-aside"><span class="aside-label">{tr(lang,'Dans ce projet','In this project')}</span><nav aria-label="{tr(lang,'Sommaire du projet','Project contents')}">{''.join(f'<a href="#{id}">{escape(h)}</a>' for id,h,t in sections)}</nav><dl><div><dt>{tr(lang,'Année','Year')}</dt><dd>{p['year']}</dd></div><div><dt>{tr(lang,'Nature','Type')}</dt><dd>{escape(txt(lang,p,'kind'))}</dd></div></dl>{tags(lang,p['tags'])}{link(path(lang,'contact')+'?project='+quote(txt(lang,p,'title')),tr(lang,'Échanger sur ce projet','Discuss this project'),'btn btn-dark')}</aside>'''
    related=[r for r in PROJECTS if r!=p][:2]
    return f'<div class="wrap detail-breadcrumb">{link(path(lang,"projets"),tr(lang,"Tous les projets","All projects"))}<span>/ {idx+1:02d}</span></div>'+pagehead(lang,txt(lang,p,'kind'),escape(txt(lang,p,'title')),txt(lang,p,'summary'))+f'<div class="wrap detail-visual" aria-hidden="true">{editorial_image("projects",idx)}</div><section class="wrap detail-layout"><article class="article-prose">{prose}<div class="article-note"><strong>{tr(lang,"Statut du travail","Work status")}</strong><p>{escape(txt(lang,p,"status"))}</p></div></article>{aside}</section><section class="section band"><div class="wrap"><h2>{tr(lang,"Autres projets","Other projects")}</h2><div class="cards-grid">'+''.join(card(lang,r,'projects',PROJECTS.index(r)) for r in related)+'</div></div></section>'


def detail_insight(lang,p):
    paras=txt(lang,p,'paragraphs')
    read=max(1,round(len(' '.join(paras).split())/180))
    prose=''.join(f'<p>{escape(t)}</p>' for t in paras)
    return f'<div class="wrap detail-breadcrumb">{link(path(lang,"publications"),tr(lang,"Toutes les notes","All writing"))}<span>{read} min {tr(lang,"de lecture","read")}</span></div>'+pagehead(lang,txt(lang,p,'kind'),escape(txt(lang,p,'title')),txt(lang,p,'summary'))+f'''<div class="wrap detail-visual note-visual" aria-hidden="true">{editorial_image("insights",INSIGHTS.index(p))}</div><section class="wrap detail-layout"><article class="article-prose note-prose">{prose}<div class="article-note"><strong>{tr(lang,'À propos de cette note','About this note')}</strong><p>{escape(txt(lang,p,'source'))}</p></div><div class="article-end"><span>{tr(lang,'Vous souhaitez en discuter ?','Would you like to discuss this?')}</span>{link(path(lang,'contact')+'?project='+quote(txt(lang,p,'title')),tr(lang,'En discuter','Discuss this'))}</div></article><aside class="detail-aside"><span class="aside-label">Hugues Emmanuel Akounna</span><p>{tr(lang,'Économie appliquée, données et politiques de développement.','Applied economics, data and development policy.')}</p><dl><div><dt>{tr(lang,'Année','Year')}</dt><dd>{p['year']}</dd></div><div><dt>{tr(lang,'Lecture','Reading time')}</dt><dd>{read} min</dd></div></dl>{tags(lang,p['tags'])}<hr>{link(path(lang,'publications'),tr(lang,'Explorer les notes','Explore the notes'))}</aside></section>'''+cta(lang)


def services(lang):
    data=[('01',tr(lang,'Études & recherche appliquée','Studies & applied research'),tr(lang,'Je vous aide à préciser la question de l’étude, à réunir les sources et à analyser le problème économique.','I help you define the study question, gather sources and analyse the economic problem.'),tr(lang,'Note de recherche · revue de littérature · synthèse','Research brief · literature review · synthesis')),('02',tr(lang,'Analyse de données','Data analysis'),tr(lang,'Je prépare et documente vos données, puis réalise l’analyse nécessaire pour produire des indicateurs et des résultats que vous pouvez interpréter.','I prepare and document your data, then carry out the analysis needed to produce indicators and findings you can interpret.'),tr(lang,'Base structurée · tableaux · script Stata · rapport','Structured data · tables · Stata script · report')),('03',tr(lang,'Suivi & reporting','Monitoring & reporting'),tr(lang,'Je vous accompagne dans le choix des indicateurs et le contrôle des données. Je prépare aussi les supports de suivi et de restitution des résultats du projet.','I support indicator design and data checks, and prepare materials for project monitoring and reporting.'),tr(lang,'Tableau de suivi · fiche indicateur · synthèse','Monitoring table · indicator sheet · summary')),('04',tr(lang,'Veille & communication analytique','Research intelligence & analytical communication'),tr(lang,'Je compare les informations disponibles et prépare des notes ou des présentations pour expliquer l’analyse à votre équipe.','I compare the available information and prepare briefs or presentations to explain the analysis to your team.'),tr(lang,'Note stratégique · présentation · supports visuels','Strategic brief · presentation · visual materials'))]
    cards=''.join(f'<article class="service-card"><span class="row-num">{n}</span><h2>{title}</h2><p>{desc}</p><div class="service-output"><span>{tr(lang,"Livrables possibles","Possible outputs")}</span>{output}</div>{link(path(lang,"contact")+"?service="+quote(title),tr(lang,"Discuter de cette mission","Discuss this assignment"))}</article>' for n,title,desc,output in data)
    steps=[(tr(lang,'Cadrer','Scope'),tr(lang,'Nous précisons la question, le contexte du travail et l’échéance.','We define the question, the context of the work and the timing.')),(tr(lang,'Analyser','Analyse'),tr(lang,'Je travaille sur les données et la méthode, avec les vérifications nécessaires.','I work on the data and method, including the checks they require.')),(tr(lang,'Partager','Share'),tr(lang,'Je vous remets le livrable avec une explication des résultats et de leurs limites.','I provide the output with an explanation of the findings and their limitations.'))]
    return pagehead(lang,tr(lang,'Services & collaborations','Services & collaboration'),tr(lang,'Un appui pour vos études<br><em>et vos données.</em>','Support for your studies<br><em>and your data.</em>'),tr(lang,'J’accompagne les équipes de recherche, les organisations de développement, les institutions et les entreprises. Nous définissons ensemble le travail à réaliser et les livrables attendus.','I support research teams, development organisations, institutions and businesses. We agree on the scope of the work and the expected outputs.'))+f'<section class="wrap service-grid">{cards}</section><section class="wrap process-section"><h2>{tr(lang,"Comment nous pouvons travailler","How we can work together")}</h2><div class="process-grid">'+''.join(f'<div><span>0{i+1}</span><h3>{title}</h3><p>{desc}</p></div>' for i,(title,desc) in enumerate(steps))+'</div></section>'+cta(lang)


def resources(lang):
    rows=[(tr(lang,'Comprendre le terrain','Understand the scope'),tr(lang,'Numérique & transformation productive','Digital adoption & productive change'),tr(lang,'La question de mon mémoire sur la CEDEAO et les vérifications encore en cours.','The question and scope of my ECOWAS thesis, with the checks still in progress.'),'publications/numerique-transformation'),(tr(lang,'Lire les données','Read the data'),tr(lang,'Quatre questions face à un indicateur','Four questions to ask of an indicator'),tr(lang,'Quatre vérifications pour comprendre ce qu’un indicateur permet de dire.','Four checks to understand what an indicator can tell you.'),'publications/donnees-politiques'),(tr(lang,'Travailler avec l’IA','Work with AI'),tr(lang,'Organiser la recherche, vérifier les résultats','Organise research, verify results'),tr(lang,'Comment vérifier les sources et les analyses quand on utilise l’IA.','How to check sources and analyses when using AI.'),'publications/ia-recherche')]
    return pagehead(lang,tr(lang,'Ressources & méthodes','Resources & methods'),tr(lang,'Lire les données<br><em>et préparer une analyse.</em>','Reading data<br><em>and preparing an analysis.</em>'),tr(lang,'Ces notes expliquent comment je lis les données et prépare un travail de recherche. Vous pouvez les utiliser pour préciser vos propres questions.','These notes explain how I read data and prepare research work. You can use them to refine your own questions.'))+f'<section class="wrap resource-list">'+''.join(f'<article><span class="row-num">0{i+1}</span><div><span class="card-meta">{label}</span><h2>{title}</h2><p>{desc}</p></div>{link(path(lang,route),tr(lang,"Lire la ressource","Read resource"))}</article>' for i,(label,title,desc,route) in enumerate(rows))+'</section>'+cta(lang)


def contact(lang):
    reasons=[('research',tr(lang,'Projet de recherche','Research project')),('data',tr(lang,'Analyse de données','Data analysis')),('development',tr(lang,'Projet de développement','Development project')),('opportunity',tr(lang,'Opportunité professionnelle','Professional opportunity')),('other',tr(lang,'Autre collaboration','Other collaboration'))]
    opts=''.join(f'<option value="{v}">{label}</option>' for v,label in reasons)
    return pagehead(lang,tr(lang,'Contact & collaboration','Contact & collaboration'),tr(lang,'Parlons de<br><em>votre projet.</em>','Let’s discuss<br><em>your project.</em>'),tr(lang,'Vous cherchez un appui pour une analyse, préparez un projet de recherche ou souhaitez me proposer de rejoindre votre équipe ? Écrivez-moi avec le contexte et vos attentes.','Do you need support with an analysis, have a research project in mind or want to discuss a role in your team? Write to me with the context and what you need.'))+f'''<section class="wrap contact-grid"><aside class="contact-primary"><span class="eyebrow">{tr(lang,'Écrire directement','Write directly')}</span><h2>{tr(lang,'Vous pouvez<br>m’écrire directement.','You can<br>email me directly.')}</h2><a class="email-large" href="mailto:{EMAIL}">{EMAIL} ↗</a><button class="copy-email" type="button" data-copy="{EMAIL}">{tr(lang,'Copier l’adresse','Copy address')} <span aria-hidden="true">⧉</span></button><span class="copy-status" role="status" aria-live="polite"></span><div class="contact-details"><span>◎ Cotonou, {tr(lang,'Bénin','Benin')}</span><span>{tr(lang,'À distance & à l’international','Remote & international')}</span><a href="{LINKEDIN}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a></div></aside><div class="contact-composer"><h2>{tr(lang,'Préparer votre message','Prepare your message')}</h2><p>{tr(lang,'Indiquez votre besoin et les informations utiles pour en discuter.','Describe what you need and the information that would help us discuss it.')}</p><noscript><p class="article-note">{tr(lang,"Pour préparer un message dans ce formulaire, activez JavaScript. Vous pouvez aussi utiliser directement le lien email.","Enable JavaScript to prepare a message with this form, or use the direct email link.")}</p></noscript><form id="contact-form" data-email="{EMAIL}"><div class="form-row"><label>{tr(lang,'Votre nom','Your name')}<input name="name" autocomplete="name" required maxlength="100" placeholder="{tr(lang,'Nom et prénom','Full name')}"></label><label>{tr(lang,'Organisation','Organisation')} <span class="optional">({tr(lang,'facultatif','optional')})</span><input name="organisation" autocomplete="organization" maxlength="140" placeholder="{tr(lang,'Votre équipe ou institution','Your team or institution')}"></label></div><label>{tr(lang,'Sujet de l’échange','What is this about?')}<select name="reason">{opts}</select></label><label>{tr(lang,'Votre question ou projet','Your question or project')}<textarea name="message" required minlength="10" maxlength="5000" rows="5" placeholder="{tr(lang,'Contexte, besoin, livrable souhaité et échéance…','Context, needs, expected output and timeline…')}"></textarea></label><button type="submit" class="btn btn-dark">{tr(lang,'Préparer un email','Prepare an email')} <span aria-hidden="true">↗</span></button><p class="form-note">{tr(lang,'Votre messagerie s’ouvrira avec un brouillon. Vous pourrez le relire et l’envoyer.','Your email application will open with a draft. You can review it and send it.')}</p><p id="form-status" class="form-status" aria-live="polite"></p><div id="email-fallback" hidden><label>{tr(lang,'Message préparé','Prepared message')}<textarea id="prepared-message" readonly rows="7"></textarea></label><p>{tr(lang,'Si votre messagerie ne s’ouvre pas, copiez ce texte et envoyez-le à l’adresse indiquée.','If your email application does not open, copy this text and send it to the address shown.')}</p></div></form></div></section>'''


def write(lang, route, title, desc, body):
    dest=OUT / ('en' if lang=='en' else '') / route / 'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(layout(lang,route,title,desc,body),encoding='utf-8')


def main():
    OUT.mkdir(exist_ok=True)
    shutil.copytree(BASE/'assets',OUT/'assets',dirs_exist_ok=True)
    for lang in ('fr','en'):
        write(lang,'',tr(lang,'Économie, données & développement','Economics, data & development'),tr(lang,'Portfolio de Hugues Emmanuel Akounna : économie appliquée, données, développement, IA et finance.','Hugues Emmanuel Akounna’s portfolio: applied economics, data, development, AI and finance.'),home(lang))
        write(lang,'apropos',tr(lang,'Mon parcours','My background'),tr(lang,'Formation, expérience et approche de Hugues Emmanuel Akounna.','Education, experience and approach of Hugues Emmanuel Akounna.'),about(lang))
        write(lang,'expertises',tr(lang,'Compétences & axes de recherche','Expertise & research interests'),tr(lang,'Économie appliquée, données, économétrie, finance, numérique et IA.','Applied economics, data, econometrics, finance, digital and AI.'),expertise(lang))
        write(lang,'projets',tr(lang,'Projets','Projects'),tr(lang,'Projets de recherche et expérience de terrain : explorer les questions, les méthodes et les limites.','Research projects and field experience: explore the questions, methods and limitations.'),pagehead(lang,tr(lang,'Projets & terrain','Projects & fieldwork'),tr(lang,'Mes projets de recherche<br><em>et de terrain.</em>','My research projects<br><em>and fieldwork.</em>'),tr(lang,'Vous trouverez ici mes projets de recherche et mes expériences de terrain. Les fiches expliquent la question étudiée, la méthode et le statut du travail. Les filtres permettent de chercher par thème ou par format.','These pages cover my research projects and field experience. Each explains the question, method and status of the work. Use the filters to search by topic or format.'))+filters(lang,PROJECTS,'projects')+cta(lang))
        for p in PROJECTS: write(lang,'projets/'+p['slug'],txt(lang,p,'title'),txt(lang,p,'summary'),detail_project(lang,p))
        write(lang,'publications',tr(lang,'Publications & notes','Writing & notes'),tr(lang,'Notes de recherche, de méthode et de pratique.','Research, methods and practice notes.'),pagehead(lang,tr(lang,'Publications & notes','Writing & notes'),tr(lang,'Mes notes de recherche<br><em>et de méthode.</em>','My notes on research<br><em>and methods.</em>'),tr(lang,'Je partage des notes de recherche et des réflexions sur les méthodes et les outils que j’utilise. Leur statut est précisé sur chaque page. Ce sont des textes de portfolio, pas des articles scientifiques publiés.','I share research notes and reflections on the methods and tools I use. Each page states the status of the text. These are portfolio pieces, not published academic articles.'))+filters(lang,INSIGHTS,'insights')+cta(lang))
        for p in INSIGHTS: write(lang,'publications/'+p['slug'],txt(lang,p,'title'),txt(lang,p,'summary'),detail_insight(lang,p))
        write(lang,'ressources',tr(lang,'Ressources & méthodes','Resources & methods'),tr(lang,'Repères accessibles pour lire les données et comprendre une démarche de recherche.','Accessible starting points for reading data and understanding a research approach.'),resources(lang))
        write(lang,'services',tr(lang,'Services & collaborations','Services & collaboration'),tr(lang,'Recherche appliquée, analyse de données, suivi et communication analytique.','Applied research, data analysis, monitoring and analytical communication.'),services(lang))
        write(lang,'contact',tr(lang,'Contact & collaboration','Contact & collaboration'),tr(lang,'Proposer une mission, un projet de recherche ou une collaboration internationale.','Discuss an assignment, research project or international collaboration.'),contact(lang))
    (OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
    print(f'Built {len(list(OUT.rglob("index.html")))} bilingual pages.')


if __name__=='__main__':
    main()
